package com.aditya.chat.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="messages") public class ChatMessage{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String chatId; @Column(nullable=false) String sender; @Column(nullable=false,length=4000) String content; @Column(nullable=false) Instant createdAt; @Column(nullable=false) String status; protected ChatMessage(){} public ChatMessage(String c,String s,String x){chatId=c;sender=s;content=x;createdAt=Instant.now();status="SENT";} public Long getId(){return id;} public String getChatId(){return chatId;} public String getSender(){return sender;} public String getContent(){return content;} public Instant getCreatedAt(){return createdAt;} public String getStatus(){return status;}}
